import{_ as e,o as a,c as t,a3 as s}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Nome completo dos documentos nos eventos","description":"","frontmatter":{"title":"Nome completo dos documentos nos eventos","id":"eproc-nome-completo-documentos","plataforma":"eproc","grupo":"Eventos","plano":"free","desde":"1.7.0","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-nome-completo-documentos.md","filePath":"funcionalidades/eproc-nome-completo-documentos.md"}'),n={name:"funcionalidades/eproc-nome-completo-documentos.md"};function d(r,o,c,i,u,m){return a(),t("div",null,o[0]||(o[0]=[s('<h1 id="nome-completo-dos-documentos-nos-eventos" tabindex="-1">Nome completo dos documentos nos eventos <a class="header-anchor" href="#nome-completo-dos-documentos-nos-eventos" aria-label="Permalink to &quot;Nome completo dos documentos nos eventos&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Na tabela de eventos, o eproc identifica cada documento por uma sigla, como &quot;CCUMPMP1&quot;. Este recurso mostra o nome completo do tipo de documento no link e deixa a sigla logo abaixo, em texto discreto.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, página do processo, links de documento da tabela de eventos.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><p>Não é preciso fazer nada. Exemplo: o link &quot;CCUMPMP1&quot; passa a mostrar &quot;Certidão de Cumprimento de Mandado de Prisão 1&quot; e, embaixo, &quot;CCUMPMP1&quot;.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Tirar o &quot;\\n&quot; que o eproc deixa no fim das observações dos documentos (ex.: documentos trasladados)</td><td>ligada</td><td>A observação &quot;Documento gerado pelo traslado de peças do processo …&quot; deixa de terminar com um &quot;\\n&quot; solto. Um &quot;\\n&quot; no meio do texto vira quebra de linha.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O nome completo vem das informações do próprio documento no eproc: o &quot;Tipo Documento&quot; do balão &quot;Informações do Documento&quot; ou, no eproc de 2º grau, a dica do link. Quando o eproc não informa o tipo, a sigla continua como está.</li><li>Funciona no eproc de 1º e de 2º grau.</li></ul>',11)]))}const h=e(n,[["render",d]]);export{p as __pageData,h as default};
